@props([ 'variant' => 'info', 'title' => null, 'icon' => null, 'dismissible' => false, 'accent' => false, ]) @php $defaultIcons = [ 'info' => 'fa-solid fa-circle-info', 'success' => 'fa-solid fa-circle-check', 'warning' => 'fa-solid fa-triangle-exclamation', 'danger' => 'fa-solid fa-circle-exclamation', ]; $iconClass = $icon ?: ($defaultIcons[$variant] ?? $defaultIcons['info']); $classes = [ 'ui-alert', 'ui-alert-' . $variant, $accent ? 'ui-alert-accent' : '', ]; $classes = trim(implode(' ', array_filter($classes))); @endphp <div {{ $attributes-> merge(['class' => $classes]) }} role="alert"> @if($iconClass) <div class="ui-alert-icon"><i class="{{ $iconClass }}"></i></div> @endif <div class="ui-alert-content"> @if($title) <div class="ui-alert-title">{{ $title }}</div> @endif <div class="ui-alert-description">{{ $slot }}</div></div> @if($dismissible) <button type="button" class="ui-alert-close" aria-label="Tutup" onclick="this.closest('.ui-alert').remove()"><i class="fa-solid fa-xmark"></i></button> @endif </div>